import { gradeOn, heldOnBy, usePeople } from '../people/usePeople';
import { claimRateOn, rateOn, totalDue, trimmedTotal, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { claimed, isOpen, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (not OPEN ones dated within their person's hold, unless stated, nor those that correct another), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. Both due and overdue totals leave out the single highest and
 * lowest person's figure when three or more people have one. Its settled-total and open-total are
 * everyone's due-total before the cap split into SETTLED and OPEN-or-PENDING claims, simply added up. Each person's own figures too. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const claims = live(all, heldOnBy(people, today));
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const dues = people.map((p) =>
    personDueCents(claims.filter((c) => c.personId === p.id), floor, rateOn(rates, gradeOn(p, today), today), (c) => claimRateOn(rates, gradeOn(p, c.date), c), late, cap),
  );
  // Everyone's due-total before the cap, split into its SETTLED and its OPEN-and-PENDING part.
  const part = (keep: (c: (typeof claims)[number]) => boolean) =>
    people.map((p) =>
      personDueCents(claims.filter((c) => c.personId === p.id && keep(c)), floor, rateOn(rates, gradeOn(p, today), today), (c) => claimRateOn(rates, gradeOn(p, c.date), c), late),
    );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (c) => claimRateOn(rates, gradeOn(p, c.date), c)),
  );
  return {
    /** Each person's own due-total (capped) and overdue-total, in cents, in the people's order. */
    perPerson: people.map((p, i) => ({ person: p, due: dues[i], overdue: over[i].cents })),
    claimedTotal: claimed(claims),
    dueTotal: trimmedTotal(dues),
    settledTotal: totalDue(part((c) => c.status === 'SETTLED')),
    openTotal: totalDue(part(isOpen)),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: trimmedTotal(over.map((o) => o.cents)),
  };
}
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { claimDueCents, isOpen, live, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, heldOn, type Person } from '../people/usePeople';
import { claimRateOn, showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';

/** Whole days from a claim's date to the sheet's today; negative for a claim dated after today. */
function ageOn(claim: Claim, today: string): number {
  return Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.date}T00:00:00Z`)) / 86_400_000);
}

/** A person's due on their OPEN and PENDING claims that count (as in their due-total: not deferred,
 *  not held unless a statement binds them), split by the claim's age on the sheet's today: 0 to 30
 *  days (a claim dated after today too), 31 to 60, and 61 or more. Not capped. */
function PersonAged({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: all = [] } = useClaims(sheet);
  const today = useSheetToday(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const lateBy = useLate(sheet);
  const claims = live(
    all.filter((c) => c.personId === person.id),
    (_, date) => heldOn(person, date, today),
  ).filter(isOpen);
  const buckets = [0n, 0n, 0n];
  for (const c of claims) {
    const due = claimDueCents(c, floor, claimRateOn(rates, gradeOn(person, c.date), c), lateBy);
    if (due === null) continue;
    const age = ageOn(c, today);
    buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2] += due;
  }
  return (
    <>
      <td data-testid="person-aged-0-30">{showDue(buckets[0])}</td>
      <td data-testid="person-aged-31-60">{showDue(buckets[1])}</td>
      <td data-testid="person-aged-61">{showDue(buckets[2])}</td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 11,
    Component: () => (
      <>
        <th>Due 0–30 days</th>
        <th>Due 31–60 days</th>
        <th>Due 61+ days</th>
      </>
    ),
  }),
  PersonCells.fill({ order: 11, Component: PersonAged }),
];
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { isActive } from '../active/active';
import { STATUSES, live, personDueCents, useClaims } from '../claims/useClaims';
import { GRADES, gradeOn, heldOn, usePeople } from '../people/usePeople';
import { periodDue, usePeriods } from '../periods/usePeriods';
import { claimRateOn, hundredths, rateOn, totalDue, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate, useReviewLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { useVoidReasons } from '../voidreasons/useVoidReasons';

/**
 * The sheet in figures, each worked out as the list works it out. Per grade: how many people not
 * retired are on it on the sheet's today, their due-totals added up (n/a ones skipped), and how many
 * of them are active. Per
 * period: its due-total, and its change from the period before it by from-date (none for the
 * earliest). Per status: how many of the sheet's claims have it, and how many REVIEW claims are review-late. Per void reason on
 * the sheet's list: how many VOID claims were voided with it.
 */
function SummaryPanel({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const { data: rates = [] } = useRates(sheet);
  const { data: voidReasons = [] } = useVoidReasons(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const reviewLate = useReviewLate(sheet);
  const people = everyone.filter((p) => !p.retired);
  const dueOf = (p: (typeof people)[number]) =>
    personDueCents(
      live(all.filter((c) => c.personId === p.id), (_, date) => heldOn(p, date, today)),
      floor,
      rateOn(rates, gradeOn(p, today), today),
      (c) => claimRateOn(rates, gradeOn(p, c.date), c),
      late,
      cap,
    );

  const periodDues = new Map(periods.map((p) => [p.name, periodDue(p, all, everyone, rates, floor, late, today)]));
  const byFrom = [...periods].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const changeOf = (p: (typeof periods)[number]) => {
    const i = byFrom.indexOf(p);
    if (i <= 0) return '';
    return totalDue([hundredths(periodDues.get(p.name)!) - hundredths(periodDues.get(byFrom[i - 1].name)!)]);
  };

  return (
    <section data-testid="summary-panel">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = people.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{totalDue(on.map(dueOf))}</td>
                <td data-testid={`summary-grade-${g}-active`}>{on.filter((p) => isActive(p, all, today)).length}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDues.get(p.name)}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{changeOf(p)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{all.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
          <tr>
            <td>REVIEW, late</td>
            <td data-testid="summary-review-late-count">{all.filter(reviewLate).length}</td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((v) => (
            <tr key={v.reason}>
              <td>{v.reason}</td>
              <td data-testid={`summary-void-${v.reason}-count`}>
                {all.filter((c) => c.status === 'VOID' && c.voidReason === v.reason).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 25, Component: SummaryPanel });

